.rating {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  color: var(--text-muted);
}
.stars { color: var(--accent); letter-spacing: 1px; }
.price-row {
  margin-top: auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 8px;
}
.price { font-weight: 700; font-size: 17px; }
.price .was {
