.newsletter input[type="email"]:focus { border-color: var(--focus); outline: none; }
.newsletter .help { font-size: 12px; color: var(--text-dim); margin-top: 8px; }
.newsletter .status[data-state="success"] { color: var(--success); }
.newsletter .status[data-state="error"] { color: var(--danger); }

