+  --success: #5cd8a8;
+  --focus: #8ab4ff;
+  --radius: 14px;
+  --radius-sm: 8px;
+  --shadow: 0 10px 30px rgba(0,0,0,.45);
+  --maxw: 1240px;
+  font-synthesis: none;
+}
+
+* { box-sizing: border-box; }
+
+html, body { margin: 0; padding: 0; }
+
+body {
+  background: radial-gradient(1200px 600px at 80% -10%, #1a1f2b 0%, #0b0d10 60%) no-repeat, var(--bg);
+  color: var(--text);
+  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Inter, "Helvetica Neue", Arial, sans-serif;
+  font-size: 16px;
+  line-height: 1.55;
+  -webkit-font-smoothing: antialiased;
+  text-rendering: optimizeLegibility;
+}
+
+img { display: block; max-width: 100%; height: auto; }
+
+a { color: inherit; }
+
+:focus-visible {
+  outline: 3px solid var(--focus);
+  outline-offset: 2px;
+  border-radius: 4px;
+}
+
+button { font: inherit; color: inherit; }
+
+.skip-link {
+  position: absolute;
+  left: 12px;
+  top: -100px;
+  background: var(--accent);
+  color: var(--accent-ink);
+  padding: 10px 14px;
+  border-radius: 8px;
+  font-weight: 700;
+  z-index: 1000;
+  text-decoration: none;
+}
+.skip-link:focus { top: 12px; }
+
+.container {
+  max-width: var(--maxw);
+  margin: 0 auto;
+  padding: 0 24px;
+}
+
+/* ---------- Top bar ---------- */
+.topbar {
+  background: #06080a;
+  border-bottom: 1px solid var(--border);
+  font-size: 13px;
+  color: var(--text-muted);
+}
+.topbar-inner {
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+  padding: 8px 24px;
+  gap: 16px;
+}
+.topbar-inner p { margin: 0; }
+.topbar-links { display: flex; gap: 18px; }
+.topbar-links a { text-decoration: none; }
+.topbar-links a:hover { color: var(--text); }
+
+/* ---------- Header ---------- */
+.site-header {
+  position: sticky;
+  top: 0;
+  z-index: 50;
+  background: rgba(11,13,16,.85);
+  backdrop-filter: saturate(140%) blur(10px);
+  border-bottom: 1px solid var(--border);
+}
+.header-inner {
+  display: grid;
+  grid-template-columns: auto 1fr auto;
+  gap: 24px;
+  align-items: center;
+  padding: 14px 24px;
+}
+.brand {
+  font-family: "Georgia", "Times New Roman", serif;
+  font-weight: 700;
+  font-size: 22px;
+  letter-spacing: 0.5px;
+  text-decoration: none;
+  color: var(--text);
+  display: inline-flex;
+  align-items: center;
+  gap: 10px;
+}
+.brand-mark {
+  width: 30px; height: 30px;
+  border-radius: 50%;
+  background: linear-gradient(135deg, var(--accent), #d97757);
+  display: inline-block;
+}
+
+.primary-nav ul {
+  list-style: none; display: flex; gap: 6px; padding: 0; margin: 0;
+  justify-content: center;
+}
+.primary-nav a {
+  display: inline-block;
+  padding: 8px 14px;
+  border-radius: 8px;
+  text-decoration: none;
+  color: var(--text-muted);
+  font-weight: 500;
+}
+.primary-nav a[aria-current="page"] { color: var(--text); background: var(--bg-elev-2); }
+.primary-nav a:hover { color: var(--text); background: var(--bg-elev); }
+
+.header-actions { display: flex; align-items: center; gap: 6px; }
+
+.icon-btn {
+  background: transparent;
+  border: 1px solid transparent;
+  color: var(--text);
+  padding: 9px;
+  border-radius: 10px;
+  cursor: pointer;
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  position: relative;
+}
+.icon-btn:hover { background: var(--bg-elev); border-color: var(--border); }
+.icon-btn svg { width: 20px; height: 20px; }
+.cart-badge {
+  position: absolute;
+  top: 2px; right: 2px;
+  min-width: 18px; height: 18px;
+  border-radius: 9px;
+  background: var(--accent);
+  color: var(--accent-ink);
+  font-size: 11px;
+  font-weight: 700;
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  padding: 0 5px;
+}
+
+.search {
+  display: flex;
+  align-items: center;
+  background: var(--bg-elev);
+  border: 1px solid var(--border);
+  border-radius: 10px;
+  padding: 6px 10px;
+  gap: 8px;
+  min-width: 220px;
+}
+.search input {
+  background: transparent;
+  border: 0;
+  outline: 0;
+  color: var(--text);
+  font: inherit;
+  width: 100%;
+  padding: 4px 0;
+}
+.search input::placeholder { color: var(--text-dim); }
+.search:focus-within { border-color: var(--focus); }
+
+/* ---------- Buttons ---------- */
+.btn {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: 8px;
+  padding: 12px 18px;
+  border-radius: 10px;
+  font-weight: 600;
+  text-decoration: none;
+  cursor: pointer;
+  border: 1px solid transparent;
+  transition: transform .08s ease, background .15s ease;
+  min-height: 44px;
+}
+.btn:active { transform: translateY(1px); }
+.btn-primary {
+  background: var(--accent);
+  color: var(--accent-ink);
+}
+.btn-primary:hover { background: var(--accent-strong); }
+.btn-ghost {
+  background: transparent;
+  color: var(--text);
+  border-color: var(--border-strong);
+}
+.btn-ghost:hover { background: var(--bg-elev); }
+
+/* ---------- Hero ---------- */
+.hero {
+  position: relative;
+  overflow: hidden;
+  border-bottom: 1px solid var(--border);
+}
+.hero-grid {
+  display: grid;
+  grid-template-columns: 1.05fr 1fr;
+  gap: 48px;
+  align-items: center;
+  padding: 72px 24px 88px;
+  max-width: var(--maxw);
+  margin: 0 auto;
+}
+.eyebrow {
+  display: inline-block;
+  font-size: 12px;
+  letter-spacing: 0.18em;
+  text-transform: uppercase;
+  color: var(--accent);
+  font-weight: 700;
+  margin-bottom: 18px;
+}
+.hero h1 {
+  font-family: "Georgia", "Times New Roman", serif;
+  font-weight: 700;
+  font-size: clamp(40px, 6vw, 68px);
+  line-height: 1.04;
+  letter-spacing: -0.02em;
+  margin: 0 0 20px;
+}
+.hero h1 em {
+  font-style: italic;
+  color: var(--accent);
+}
+.hero p.lede {
+  font-size: 18px;
+  color: var(--text-muted);
+  max-width: 52ch;
+  margin: 0 0 28px;
+}
+.hero-cta { display: flex; gap: 12px; flex-wrap: wrap; }
+.hero-meta {
+  margin-top: 36px;
+  display: flex;
+  gap: 28px;
+  color: var(--text-dim);
+  font-size: 14px;
+}
+.hero-meta strong { color: var(--text); display: block; font-size: 18px; font-weight: 700; }
+
+.hero-art {
+  position: relative;
+  aspect-ratio: 4/5;
+  border-radius: 20px;
+  overflow: hidden;
+  background: #1a1d23;
+  box-shadow: var(--shadow);
+}
+.hero-art img { width: 100%; height: 100%; object-fit: cover; }
+.hero-tag {
+  position: absolute;
+  bottom: 16px; left: 16px;
+  background: rgba(11,13,16,.78);
+  border: 1px solid var(--border);
+  backdrop-filter: blur(8px);
+  padding: 12px 14px;
+  border-radius: 12px;
+  display: flex;
+  align-items: center;
+  gap: 12px;
+  max-width: 260px;
+}
+.hero-tag .swatch {
+  width: 36px; height: 36px; border-radius: 8px;
+  background: linear-gradient(135deg, #d97757, #f5b54a);
+  flex-shrink: 0;
+}
+.hero-tag-text strong { display: block; font-size: 14px; }
+.hero-tag-text span { font-size: 12px; color: var(--text-dim); }
+
+/* ---------- Marquee strip ---------- */
+.strip {
+  background: #06080a;
+  border-bottom: 1px solid var(--border);
+  padding: 14px 0;
+  overflow: hidden;
+}
+.strip-inner {
+  display: flex;
+  gap: 48px;
+  flex-wrap: wrap;
+  justify-content: center;
+  color: var(--text-dim);
+  font-size: 13px;
+  letter-spacing: 0.06em;
+  text-transform: uppercase;
+}
+.strip-inner span { display: inline-flex; align-items: center; gap: 8px; }
+.strip-inner svg { width: 16px; height: 16px; color: var(--accent); }
+
+/* ---------- Section ---------- */
+.section { padding: 80px 0; }
+.section-header {
+  display: flex;
+  justify-content: space-between;
+  align-items: end;
+  gap: 24px;
+  margin-bottom: 32px;
+  flex-wrap: wrap;
+}
+.section-header h2 {
+  font-family: "Georgia", serif;
+  font-size: clamp(28px, 3.4vw, 38px);
+  margin: 0;
+  letter-spacing: -0.01em;
+}
+.section-header .eyebrow { margin-bottom: 8px; }
+.section-header .sub { color: var(--text-muted); margin: 6px 0 0; max-width: 56ch; }
+.section-link {
+  text-decoration: none;
+  color: var(--text);
+  font-weight: 600;
+  border-bottom: 1px solid var(--border-strong);
+  padding-bottom: 2px;
+}
+.section-link:hover { color: var(--accent); border-color: var(--accent); }
+
+/* ---------- Categories ---------- */
+.categories {
+  display: grid;
+  grid-template-columns: repeat(4, 1fr);
+  gap: 16px;
+}
+.category-card {
+  position: relative;
+  aspect-ratio: 4/5;
+  border-radius: var(--radius);
+  overflow: hidden;
+  background: var(--bg-elev);
+  border: 1px solid var(--border);
+  text-decoration: none;
+  color: var(--text);
+  display: block;
+  isolation: isolate;
+}
+.category-card img {
+  width: 100%; height: 100%; object-fit: cover;
+  transition: transform .5s ease;
+}
+.category-card:hover img { transform: scale(1.05); }
+.category-card::after {
+  content: "";
+  position: absolute; inset: 0;
+  background: linear-gradient(180deg, rgba(0,0,0,0) 40%, rgba(0,0,0,.85) 100%);
+  z-index: 1;
+}
+.category-card .label {
+  position: absolute;
+  left: 16px; bottom: 14px; right: 16px;
+  z-index: 2;
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+}
+.category-card .label strong { font-size: 18px; }
+.category-card .label span { color: var(--text-muted); font-size: 13px; }
+
+/* ---------- Product grid ---------- */
+.product-grid {
+  display: grid;
+  grid-template-columns: repeat(4, 1fr);
+  gap: 22px;
+}
+.product-card {
+  background: var(--bg-elev);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+  transition: border-color .2s ease, transform .2s ease;
+}
+.product-card:hover { border-color: var(--border-strong); transform: translateY(-2px); }
+.product-media {
+  position: relative;
+  aspect-ratio: 1/1;
+  background: #1a1d23;
+  overflow: hidden;
+}
+.product-media img { width: 100%; height: 100%; object-fit: cover; }
+.product-badge {
+  position: absolute;
+  top: 12px; left: 12px;
+  background: var(--bg-elev-2);
+  border: 1px solid var(--border-strong);
+  color: var(--text);
+  font-size: 11px;
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+  padding: 5px 9px;
+  border-radius: 6px;
+  font-weight: 700;
+}
+.product-badge.new { background: var(--accent); color: var(--accent-ink); border-color: transparent; }
+.product-badge.sale { background: #3b1a1a; color: #ffb0b0; border-color: #5a2424; }
+
+.fav-btn {
+  position: absolute;
+  top: 10px; right: 10px;
+  width: 36px; height: 36px;
+  border-radius: 50%;
+  background: rgba(11,13,16,.8);
+  border: 1px solid var(--border);
+  color: var(--text-muted);
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  cursor: pointer;
+}
+.fav-btn:hover { color: var(--accent); }
+.fav-btn[aria-pressed="true"] { color: var(--accent); border-color: var(--accent); }
+.fav-btn svg { width: 18px; height: 18px; }
+
+.product-info { padding: 16px; display: flex; flex-direction: column; gap: 8px; flex: 1; }
+.product-info .cat {
+  font-size: 11px;
+  text-transform: uppercase;
+  letter-spacing: 0.1em;
+  color: var(--text-dim);
+}
+.product-title {
+  font-size: 15px;
+  font-weight: 600;
+  margin: 0;
+  color: var(--text);
+}
+.product-title a { text-decoration: none; }
+.product-title a:hover { color: var(--accent); }
+.rating {
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+  font-size: 13px;
+  color: var(--text-muted);
+}
+.stars { color: var(--accent); letter-spacing: 1px; }
+.price-row {
+  margin-top: auto;
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+  padding-top: 8px;
+}
+.price { font-weight: 700; font-size: 17px; }
+.price .was {
+  font-weight: 500;
+  color: var(--text-dim);
+  text-decoration: line-through;
+  margin-right: 6px;
+  font-size: 14px;
+}
+.add-btn {
+  background: var(--bg-elev-2);
+  border: 1px solid var(--border-strong);
+  color: var(--text);
+  padding: 8px 12px;
+  border-radius: 8px;
+  font-weight: 600;
+  font-size: 13px;
+  cursor: pointer;
+  min-height: 36px;
+}
+.add-btn:hover { background: var(--accent); color: var(--accent-ink); border-color: transparent; }
+
+/* ---------- Deals ---------- */
+.deals {
+  display: grid;
+  grid-template-columns: 1.4fr 1fr 1fr;
+  gap: 18px;
+}
+.deal-card {
+  border-radius: var(--radius);
+  padding: 32px;
+  position: relative;
+  overflow: hidden;
+  border: 1px solid var(--border);
+  display: flex;
+  flex-direction: column;
+  justify-content: space-between;
+  min-height: 320px;
+  isolation: isolate;
+}
+.deal-card.feature {
+  background: linear-gradient(135deg, #2a1d10 0%, #1a1208 60%);
+  border-color: #3a2a14;
+}
+.deal-card.feature::before {
+  content: "";
+  position: absolute;
+  inset: 0;
+  background: radial-gradient(400px 220px at 90% 10%, rgba(245,181,74,.18), transparent 60%);
+  z-index: -1;
+}
+.deal-card.alt {
+  background: linear-gradient(160deg, #122023 0%, #0d1518 100%);
+  border-color: #1c2c30;
+}
+.deal-card.dim { background: var(--bg-elev); }
+
+.deal-card h3 {
+  font-family: "Georgia", serif;
+  font-size: 28px;
+  margin: 0 0 8px;
+  line-height: 1.15;
+}
+.deal-card.feature h3 { font-size: 36px; }
+.deal-card p { color: var(--text-muted); margin: 0 0 20px; }
+
+.countdown {
+  display: flex;
+  gap: 10px;
+  margin: 18px 0 22px;
+}
+.countdown div {
+  background: rgba(0,0,0,.4);
+  border: 1px solid var(--border);
+  border-radius: 10px;
+  padding: 10px 12px;
+  text-align: center;
+  min-width: 64px;
+}
+.countdown strong {
+  display: block;
+  font-size: 22px;
+  font-variant-numeric: tabular-nums;
+}
+.countdown span {
+  font-size: 11px;
+  color: var(--text-dim);
+  text-transform: uppercase;
+  letter-spacing: 0.1em;
+}
+
+.deal-card .tag {
+  display: inline-block;
+  background: rgba(245,181,74,.15);
+  color: var(--accent-strong);
+  border: 1px solid rgba(245,181,74,.35);
+  font-size: 12px;
+  font-weight: 700;
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+  padding: 5px 10px;
+  border-radius: 999px;
+  margin-bottom: 14px;
+  width: fit-content;
+}
+
+/* ---------- Editorial ---------- */
+.editorial {
+  display: grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: 22px;
+}
+.article-card {
+  background: var(--bg-elev);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+  text-decoration: none;
+  color: var(--text);
+  transition: transform .2s ease, border-color .2s ease;
+}
+.article-card:hover { transform: translateY(-2px); border-color: var(--border-strong); }
+.article-media { aspect-ratio: 16/10; overflow: hidden; }
+.article-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .5s ease; }
+.article-card:hover .article-media img { transform: scale(1.04); }
+.article-body { padding: 22px; }
+.article-body .meta {
+  font-size: 12px;
+  text-transform: uppercase;
+  letter-spacing: 0.08em;
+  color: var(--accent);
+  margin-bottom: 8px;
+}
+.article-body h3 {
+  font-family: "Georgia", serif;
+  font-size: 22px;
+  margin: 0 0 8px;
+  line-height: 1.25;
+}
+.article-body p { color: var(--text-muted); margin: 0; font-size: 14px; }
+
+/* ---------- Newsletter ---------- */
+.newsletter {
+  background: linear-gradient(135deg, #14171c, #0e1115);
+  border-top: 1px solid var(--border);
+  border-bottom: 1px solid var(--border);
+}
+.newsletter-inner {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 40px;
+  align-items: center;
+  padding: 64px 24px;
+}
+.newsletter h2 {
+  font-family: "Georgia", serif;
+  font-size: 34px;
+  margin: 0 0 10px;
+  letter-spacing: -0.01em;
+}
+.newsletter p { color: var(--text-muted); margin: 0; }
+.newsletter form {
+  display: flex;
+  gap: 10px;
+  flex-wrap: wrap;
+}
+.newsletter label { display: block; font-size: 13px; margin-bottom: 8px; color: var(--text-muted); }
+.newsletter .field {
+  flex: 1;
+  min-width: 240px;
+}
+.newsletter input[type="email"] {
+  width: 100%;
+  background: var(--bg);
+  border: 1px solid var(--border-strong);
+  color: var(--text);
+  padding: 14px 16px;
+  border-radius: 10px;
+  font: inherit;
+  min-height: 48px;
+}
+.newsletter input[type="email"]:focus { border-color: var(--focus); outline: none; }
+.newsletter .help { font-size: 12px; color: var(--text-dim); margin-top: 8px; }
+.newsletter .status[data-state="success"] { color: var(--success); }
+.newsletter .status[data-state="error"] { color: var(--danger); }
+
+/* ---------- Footer ---------- */
+.site-footer {
+  background: #06080a;
+  padding: 56px 0 28px;
+  color: var(--text-muted);
+  font-size: 14px;
+}
+.footer-grid {
+  display: grid;
+  grid-template-columns: 1.4fr 1fr 1fr 1fr;
+  gap: 40px;
+  margin-bottom: 40px;
+}
+.footer-grid h3 {
+  color: var(--text);
+  font-size: 14px;
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+  margin: 0 0 14px;
+}
+.footer-grid ul { list-style: none; padding: 0; margin: 0; display: grid; gap: 10px; }
+.footer-grid a { text-decoration: none; }
+.footer-grid a:hover { color: var(--text); }
+.footer-bottom {
+  border-top: 1px solid var(--border);
+  padding-top: 20px;
+  display: flex;
+  justify-content: space-between;
+  flex-wrap: wrap;
+  gap: 12px;
+  color: var(--text-dim);
+  font-size: 13px;
+}
+
+/* ---------- Toast ---------- */
+.toast-region {
+  position: fixed;
+  bottom: 24px;
+  right: 24px;
+  display: flex;
+  flex-direction: column;
+  gap: 10px;
+  z-index: 1000;
+}
+.toast {
+  background: var(--bg-elev-2);
+  border: 1px solid var(--border-strong);
+  border-left: 3px solid var(--accent);
+  padding: 12px 16px;
+  border-radius: 10px;
+  box-shadow: var(--shadow);
+  max-width: 320px;
+  font-size: 14px;
+}
+
+/* ---------- Responsive ---------- */
+@media (max-width: 1000px) {
+  .hero-grid { grid-template-columns: 1fr; padding: 56px 24px; gap: 32px; }
+  .categories { grid-template-columns: repeat(2, 1fr); }
+  .product-grid { grid-template-columns: repeat(2, 1fr); }
+  .deals { grid-template-columns: 1fr 1fr; }
+  .deal-card.feature { grid-column: 1 / -1; }
+  .editorial { grid-template-columns: 1fr; }
+  .newsletter-inner { grid-template-columns: 1fr; padding: 48px 24px; }
+  .footer-grid { grid-template-columns: 1fr 1fr; }
+  .header-inner { grid-template-columns: auto 1fr auto; }
+  .primary-nav { display: none; }
+  .search { min-width: 0; flex: 1; }
+}
+
+@media (max-width: 600px) {
+  .topbar-links { display: none; }
+  .section { padding: 56px 0; }
+  .deals { grid-template-columns: 1fr; }
+  .footer-grid { grid-template-columns: 1fr; }
+  .hero-meta { flex-wrap: wrap; gap: 18px; }
+  .header-inner { gap: 12px; padding: 12px 16px; }
+  .container { padding: 0 16px; }
+  .search { display: none; }
+}
+
+@media (prefers-reduced-motion: reduce) {
