                {c.links.map((l) => <li key={l}><a href={`#${l.toLowerCase().replace(/\s+/g,'-')}`}>{l}</a></li>)}
              </ul>
            </nav>
          ))}
        </div>
        <div className="footer-bottom">
          <span>© {new Date().getFullYear()} Lumen &amp; Co. All rights reserved.</span>
          <span>
            <a href="#privacy" style={{textDecoration:"none", marginRight: 16}}>Privacy</a>
            <a href="#terms" style={{textDecoration:"none", marginRight: 16}}>Terms</a>
            <a href="#cookies" style={{textDecoration:"none"}}>Cookies</a>
          </span>
        </div>
      </div>
    </footer>
  );
}

function Toasts({ items }) {
  return (
    <div className="toast-region" role="region" aria-label="Notifications" aria-live="polite">
      {items.map((t) => (
        <div className="toast" key={t.id}>{t.msg}</div>
      ))}
    </div>
  );
}

/* ----------------------------- App ----------------------------- */
function App() {
  const [favs, setFavs] = useState(() => new Set());
  const [cart, setCart] = useState([]);
  const [toasts, setToasts] = useState([]);
  const idRef = useRef(0);

  const toggleFav = useCallback((id) => {
    setFavs((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  }, []);

  const addToCart = useCallback((p) => {
    setCart((prev) => [...prev, p]);
    const id = ++idRef.current;
    setToasts((prev) => [...prev, { id, msg: `${p.title} added to your cart.` }]);
    setTimeout(() => setToasts((prev) => prev.filter((t) => t.id !== id)), 3500);
  }, []);

  return (
    <>
      <Topbar />
      <Header cartCount={cart.length} favCount={favs.size} />
      <main id="main" tabIndex="-1">
        <Hero />
        <ValueStrip />
        <Categories />
        <FeaturedProducts favs={favs} onFav={toggleFav} onAdd={addToCart} />
        <Deals />
        <Editorial />
        <Newsletter />
      </main>
      <Footer />
      <Toasts items={toasts} />
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);
