function Newsletter() {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState({ state: "idle", msg: "" });

  const submit = (e) => {
    e.preventDefault();
    const ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    if (!ok) {
      setStatus({ state: "error", msg: "Please enter a valid email address." });
      return;
    }
    setStatus({ state: "success", msg: `Thanks — we'll send updates to ${email}.` });
    setEmail("");
  };

  return (
    <section className="newsletter" aria-labelledby="news-heading">
      <div className="newsletter-inner container">
        <div>
          <h2 id="news-heading">Join the Society</h2>
          <p>Quiet emails — new releases, restocks, and the occasional reading list. No spam.</p>
