  const d = Math.floor(diff / 86400000);
  const h = Math.floor((diff / 3600000) % 24);
  const m = Math.floor((diff / 60000) % 60);
  const s = Math.floor((diff / 1000) % 60);
  return { d, h, m, s };
}

function Deals() {
  const target = useMemo(() => Date.now() + 1000 * 60 * 60 * 38 + 1000 * 23, []);
  const { d, h, m, s } = useCountdown(target);
  const pad = (n) => String(n).padStart(2, "0");

  return (
    <section className="section" aria-labelledby="deals-heading" id="deals" style={{paddingTop: 0}}>
      <div className="container">
        <div className="section-header">
          <div>
            <span className="eyebrow">Limited time</span>
            <h2 id="deals-heading">Deals worth a look</h2>
            <p className="sub">Three offers running this week — once they're gone, they're gone.</p>
          </div>
          <a href="#sale" className="section-link">All offers</a>
        </div>
        <div className="deals">
          <article className="deal-card feature" aria-labelledby="deal-1-h">
            <div>
              <span className="tag">Flash sale · 38 hours left</span>
              <h3 id="deal-1-h">Up to 40% off outerwear</h3>
              <p>Last season's coats and jackets, drastically reduced. Selected colors and sizes only.</p>
              <div className="countdown" role="timer" aria-live="off"
                aria-label={`Sale ends in ${d} days, ${h} hours, ${m} minutes`}>
                <div><strong>{pad(d)}</strong><span>Days</span></div>
                <div><strong>{pad(h)}</strong><span>Hours</span></div>
                <div><strong>{pad(m)}</strong><span>Minutes</span></div>
                <div><strong>{pad(s)}</strong><span>Seconds</span></div>
              </div>
            </div>
            <a href="#sale-outerwear" className="btn btn-primary" style={{width:"fit-content"}}>
              Shop the sale <Icon name="arrow" />
            </a>
          </article>

          <article className="deal-card alt" aria-labelledby="deal-2-h">
            <div>
              <span className="tag">Bundle</span>
              <h3 id="deal-2-h">Buy two knits, save 20%</h3>
              <p>Mix and match merino, cashmere, and lambswool styles. Discount applied at checkout.</p>
            </div>
            <a href="#knits" className="btn btn-ghost" style={{width:"fit-content"}}>
              Browse knitwear <Icon name="arrow" />
            </a>
          </article>

          <article className="deal-card dim" aria-labelledby="deal-3-h">
            <div>
              <span className="tag">Members only</span>
              <h3 id="deal-3-h">Early access to new arrivals</h3>
              <p>Sign up free and shop new releases 48 hours before everyone else.</p>
            </div>
            <a href="#membership" className="btn btn-ghost" style={{width:"fit-content"}}>
              Join Lumen Society <Icon name="arrow" />
            </a>
          </article>
        </div>
      </div>
    </section>
  );
}

function Editorial() {
  return (
    <section className="section" aria-labelledby="editorial-heading" id="editorial" style={{paddingTop: 0}}>
      <div className="container">
        <div className="section-header">
          <div>
            <span className="eyebrow">The Journal</span>
            <h2 id="editorial-heading">Stories &amp; field notes</h2>
            <p className="sub">Long reads, guides, and conversations with the people behind the goods we sell.</p>
          </div>
          <a href="#journal" className="section-link">All stories</a>
        </div>
        <div className="editorial">
          {ARTICLES.map((a) => (
            <a className="article-card" href={`#${a.id}`} key={a.id}>
              <div className="article-media">
                <img src={a.img} alt="" loading="lazy" />
              </div>
              <div className="article-body">
                <div className="meta">{a.tag} · 6 min read</div>
                <h3>{a.title}</h3>
                <p>{a.excerpt}</p>
              </div>
            </a>
          ))}
        </div>
      </div>
    </section>
  );
}

function Newsletter() {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState({ state: "idle", msg: "" });

  const submit = (e) => {
    e.preventDefault();
    const ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    if (!ok) {
      setStatus({ state: "error", msg: "Please enter a valid email address." });
      return;
    }
    setStatus({ state: "success", msg: `Thanks — we'll send updates to ${email}.` });
    setEmail("");
  };

  return (
    <section className="newsletter" aria-labelledby="news-heading">
      <div className="newsletter-inner container">
        <div>
          <h2 id="news-heading">Join the Society</h2>
          <p>Quiet emails — new releases, restocks, and the occasional reading list. No spam.</p>
        </div>
        <form onSubmit={submit} noValidate aria-describedby="news-help news-status">
          <div className="field">
            <label htmlFor="news-email">Email address</label>
            <input
              id="news-email"
              type="email"
              required
              autoComplete="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              aria-invalid={status.state === "error"}
            />
            <p id="news-help" className="help">We'll only use this to send our newsletter.</p>
            <p id="news-status" className="status" data-state={status.state} aria-live="polite">
              {status.msg}
            </p>
          </div>
          <button type="submit" className="btn btn-primary" style={{alignSelf:"start", marginTop: 28}}>
            Subscribe
          </button>
        </form>
      </div>
    </section>
  );
}

function Footer() {
  const cols = [
    { title: "Shop", links: ["Women", "Men", "Home", "Accessories", "Sale", "Gift cards"] },
    { title: "Service", links: ["Contact us", "Shipping", "Returns", "Size guide", "Care guides"] },
    { title: "Company", links: ["About Lumen", "Sustainability", "Stores", "Careers", "Press"] },
  ];
  return (
    <footer className="site-footer">
      <div className="container">
        <div className="footer-grid">
          <div>
            <a href="#home" className="brand" style={{marginBottom: 12}}>
              <span className="brand-mark" aria-hidden="true"></span> Lumen &amp; Co.
            </a>
            <p style={{marginTop: 16, maxWidth: "36ch"}}>
              An independent retailer of considered, well-made goods for everyday life.
              Founded in Copenhagen, 2014.
            </p>
          </div>
          {cols.map((c) => (
            <nav key={c.title} aria-label={c.title}>
              <h3>{c.title}</h3>
              <ul>
                {c.links.map((l) => <li key={l}><a href={`#${l.toLowerCase().replace(/\s+/g,'-')}`}>{l}</a></li>)}
              </ul>
            </nav>
          ))}
        </div>
        <div className="footer-bottom">
          <span>© {new Date().getFullYear()} Lumen &amp; Co. All rights reserved.</span>
          <span>
            <a href="#privacy" style={{textDecoration:"none", marginRight: 16}}>Privacy</a>
            <a href="#terms" style={{textDecoration:"none", marginRight: 16}}>Terms</a>
            <a href="#cookies" style={{textDecoration:"none"}}>Cookies</a>
          </span>
        </div>
      </div>
    </footer>
  );
}

function Toasts({ items }) {
  return (
    <div className="toast-region" role="region" aria-label="Notifications" aria-live="polite">
      {items.map((t) => (
        <div className="toast" key={t.id}>{t.msg}</div>
      ))}
    </div>
  );
}

/* ----------------------------- App ----------------------------- */
function App() {
  const [favs, setFavs] = useState(() => new Set());
  const [cart, setCart] = useState([]);
  const [toasts, setToasts] = useState([]);
  const idRef = useRef(0);

  const toggleFav = useCallback((id) => {
    setFavs((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  }, []);

  const addToCart = useCallback((p) => {
    setCart((prev) => [...prev, p]);
    const id = ++idRef.current;
    setToasts((prev) => [...prev, { id, msg: `${p.title} added to your cart.` }]);
    setTimeout(() => setToasts((prev) => prev.filter((t) => t.id !== id)), 3500);
  }, []);

  return (
    <>
      <Topbar />
      <Header cartCount={cart.length} favCount={favs.size} />
      <main id="main" tabIndex="-1">
        <Hero />
        <ValueStrip />
        <Categories />
        <FeaturedProducts favs={favs} onFav={toggleFav} onAdd={addToCart} />
        <Deals />
        <Editorial />
        <Newsletter />
      </main>
      <Footer />
      <Toasts items={toasts} />
    </>
  );
}

