}
.hero-meta > div { display: flex; flex-direction: column; }
.hero-meta strong { color: var(--text); display: block; font-size: 18px; font-weight: 700; }
.hero-meta dt { order: 2; }
.hero-meta dd { order: 1; margin: 0; }

.hero-art {
