.category-card .label {
  position: absolute;
  left: 16px; bottom: 14px; right: 16px;
  z-index: 2;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.category-card .label strong { font-size: 18px; }
.category-card .label span { color: var(--text-muted); font-size: 13px; }

/* ---------- Product grid ---------- */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 22px;
}
.product-card {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
