  color: var(--text-dim);
  text-decoration: line-through;
  margin-right: 6px;
  font-size: 14px;
}
.add-btn {
  background: var(--bg-elev-2);
  border: 1px solid var(--border-strong);
  color: var(--text);
  padding: 8px 12px;
  border-radius: 8px;
  font-weight: 600;
  font-size: 13px;
  cursor: pointer;
  min-height: 36px;
}
.add-btn:hover { background: var(--accent); color: var(--accent-ink); border-color: transparent; }

/* ---------- Deals ---------- */
.deals {
