  border: 1px solid var(--border-strong);
  border-left: 3px solid var(--accent);
  padding: 12px 16px;
  border-radius: 10px;
  box-shadow: var(--shadow);
  max-width: 320px;
  font-size: 14px;
}

/* ---------- Responsive ---------- */
@media (max-width: 1000px) {
