  border-radius: 20px;
  overflow: hidden;
  background: #1a1d23;
  box-shadow: var(--shadow);
}
.hero-art img { width: 100%; height: 100%; object-fit: cover; }
.hero-tag {
  position: absolute;
  bottom: 16px; left: 16px;
  background: rgba(11,13,16,.78);
  border: 1px solid var(--border);
  backdrop-filter: blur(8px);
  padding: 12px 14px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  gap: 12px;
  max-width: 260px;
}
.hero-tag .swatch {
  width: 36px; height: 36px; border-radius: 8px;
  background: linear-gradient(135deg, #d97757, #f5b54a);
  flex-shrink: 0;
}
.hero-tag-text strong { display: block; font-size: 14px; }
.hero-tag-text span { font-size: 12px; color: var(--text-dim); }

/* ---------- Marquee strip ---------- */
.strip {
  background: #06080a;
  border-bottom: 1px solid var(--border);
  padding: 14px 0;
  overflow: hidden;
}
.strip-inner {
  display: flex;
  gap: 48px;
  flex-wrap: wrap;
  justify-content: center;
  color: var(--text-dim);
  font-size: 13px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.strip-inner span { display: inline-flex; align-items: center; gap: 8px; }
.strip-inner svg { width: 16px; height: 16px; color: var(--accent); }

/* ---------- Section ---------- */
.section { padding: 80px 0; }
.section-header {
  display: flex;
  justify-content: space-between;
  align-items: end;
  gap: 24px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}
.section-header h2 {
  font-family: "Georgia", serif;
  font-size: clamp(28px, 3.4vw, 38px);
  margin: 0;
  letter-spacing: -0.01em;
}
.section-header .eyebrow { margin-bottom: 8px; }
.section-header .sub { color: var(--text-muted); margin: 6px 0 0; max-width: 56ch; }
.section-link {
  text-decoration: none;
  color: var(--text);
  font-weight: 600;
  border-bottom: 1px solid var(--border-strong);
  padding-bottom: 2px;
}
.section-link:hover { color: var(--accent); border-color: var(--accent); }

/* ---------- Categories ---------- */
.categories {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.category-card {
  position: relative;
  aspect-ratio: 4/5;
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  text-decoration: none;
  color: var(--text);
  display: block;
  isolation: isolate;
}
.category-card img {
  width: 100%; height: 100%; object-fit: cover;
  transition: transform .5s ease;
}
.category-card:hover img { transform: scale(1.05); }
.category-card::after {
  content: "";
  position: absolute; inset: 0;
  background: linear-gradient(180deg, rgba(0,0,0,0) 40%, rgba(0,0,0,.85) 100%);
  z-index: 1;
}
.category-card .label {
  position: absolute;
  left: 16px; bottom: 14px; right: 16px;
  z-index: 2;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.category-card .label strong { font-size: 18px; }
.category-card .label span { color: var(--text-muted); font-size: 13px; }

/* ---------- Product grid ---------- */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 22px;
}
.product-card {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
