  align-items: center;
  justify-content: center;
  cursor: pointer;
}
.fav-btn:hover { color: var(--accent); }
.fav-btn[aria-pressed="true"] { color: var(--accent); border-color: var(--accent); }
.fav-btn svg { width: 18px; height: 18px; }

.product-info { padding: 16px; display: flex; flex-direction: column; gap: 8px; flex: 1; }
.product-info .cat {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-dim);
}
.product-title {
  font-size: 15px;
  font-weight: 600;
  margin: 0;
  color: var(--text);
}
.product-title a { text-decoration: none; }
.product-title a:hover { color: var(--accent); }
.rating {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  color: var(--text-muted);
}
.stars { color: var(--accent); letter-spacing: 1px; }
.price-row {
  margin-top: auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 8px;
}
.price { font-weight: 700; font-size: 17px; }
.price .was {
  font-weight: 500;
  color: var(--text-dim);
  text-decoration: line-through;
  margin-right: 6px;
  font-size: 14px;
}
.add-btn {
  background: var(--bg-elev-2);
  border: 1px solid var(--border-strong);
  color: var(--text);
  padding: 8px 12px;
  border-radius: 8px;
  font-weight: 600;
  font-size: 13px;
  cursor: pointer;
  min-height: 36px;
}
.add-btn:hover { background: var(--accent); color: var(--accent-ink); border-color: transparent; }

/* ---------- Deals ---------- */
.deals {
